});

workbooksRouter.patch("/api/workbooks/:id", (req: Request, res: Response) => {
  const wb = getWorkbook(req.params.id);
  if (!wb) {
    notFound(res);
    return;
  }
  const rawName = typeof req.body?.name === "string" ? req.body.name : "";
  const name = rawName.trim();
  if (!name) {
